from itertools import combinations

g = 22
clique_size_red = 5
clique_size_blue = 4

edges = list(combinations(range(g), 2))

for coloring in range(2**len(edges)):
    coloring = [(coloring >> i) & 1 for i in range(len(edges))]

    valid = True
    for clique_size, color in [(clique_size_red, 0), (clique_size_blue, 1)]:
        for clique in combinations(range(g), clique_size):
            clique_edges = [edges.index((min(i, j), max(i, j))) for i, j in combinations(clique, 2)]
            if all(coloring[edge] == color for edge in clique_edges):
                valid = False
                break
        if not valid:
            break

    if valid:
        print(' '.join(map(str, coloring)))
        break
else:
    print("UNSATISFIABLE")
